  `teaching_review` longtext NOT NULL,
  `courses_review` longtext NOT NULL,
  `library_review` longtext NOT NULL,
  `research_review` longtext NOT NULL,
  `internship_review` longtext NOT NULL,
  `infrastructure_review` longtext NOT NULL,
  `administration_review` longtext NOT NULL,
