  `type_of_student` varchar(20) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `category` varchar(10) DEFAULT NULL,
  `year_of_starting` int DEFAULT NULL,
  `college_code` varchar(10) DEFAULT NULL,
  `phone_number` varchar(15) NOT NULL,
