  `profile_completed` tinyint(1) NOT NULL,
  `unique_key` varchar(6) DEFAULT NULL,
  `is_verified_student` tinyint(1) NOT NULL,
  `usn` varchar(20) DEFAULT NULL,
  `id_card_image` longblob,
  PRIMARY KEY (`student_user_id`),
  UNIQUE KEY `email_id` (`email_id`),
  UNIQUE KEY `usn` (`usn`),
  KEY `student_unique_key_c5640144_fk_branch_unique_key` (`unique_key`),
