/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `before_student_insert` BEFORE INSERT ON `student` FOR EACH ROW BEGIN
    DECLARE next_id INT;
    DECLARE current_year CHAR(4);

    
    SET current_year = YEAR(CURDATE());

    
    INSERT INTO student_counter VALUES ();
    SET next_id = LAST_INSERT_ID();

    
    IF NEW.type_of_student = 'counselling' THEN

        SET NEW.student_user_id = CONCAT(
            current_year,
            LPAD(next_id, 6, '0')
        );

    
    ELSEIF NEW.type_of_student = 'studying' THEN

        SET NEW.student_user_id = CONCAT(
            NEW.college_code,
            LPAD(next_id, 6, '0')
        );

    END IF;
END */;;
